          <div className="w-10 h-10 bg-gradient-to-tr from-[#00ff88] to-emerald-400 rounded-lg flex items-center justify-center neon-glow group-hover:scale-110 transition-transform">
            <span className="text-black font-extrabold text-xl italic">X</span>
          </div>
          <span className="text-xl font-bold tracking-tighter chrome-text">CHROME<span className="text-[#00ff88]">MEDIA</span></span>
        </Link>

        <div className="flex items-center gap-8">
          <Link to="/" className="text-sm font-medium hover:text-[#00ff88] transition-colors">HOME</Link>
          <Link to="/works" className="text-sm font-medium hover:text-[#00ff88] transition-colors">WORKS</Link>
          <a href="#contact" className="hidden md:block px-5 py-2 rounded-full border border-[#00ff88] text-[#00ff88] text-sm font-bold hover:bg-[#00ff88] hover:text-black transition-all duration-300">
            HIRE US
          </a>
        </div>
      </div>
    </nav>
  );
};

export default Navbar;

import React from 'react';

interface AutoSliderProps {
