import React, { useRef, useEffect, useState } from 'react';

interface AutoSliderProps {
  items: React.ReactNode[];
  speed?: 'slow' | 'normal' | 'fast';
  reverse?: boolean;
}

const AutoSlider: React.FC<AutoSliderProps> = ({ items, speed = 'normal' }) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const [isInteracting, setIsInteracting] = useState(false);
  const interactionTimerRef = useRef<number | null>(null);

  // Dynamic cycle timings (ms) and scroll distance
  const timings = {
    slow: { moveInterval: 4000, scrollAmount: 400 },
    normal: { moveInterval: 2500, scrollAmount: 450 },
    fast: { moveInterval: 1800, scrollAmount: 500 } // Faster cycles
  };

  const { moveInterval, scrollAmount } = timings[speed];

  useEffect(() => {
    const container = containerRef.current;
    if (!container) return;

    let intervalId: number;

    const startAutoScroll = () => {
      intervalId = window.setInterval(() => {
        // Pause auto-movement if the user is currently scrolling or hovering
        if (!container || isInteracting) return;

        const { scrollLeft, scrollWidth } = container;
        const halfWidth = scrollWidth / 2;

        // Infinite loop logic: Check if we've reached the halfway point of the duplicated list
        if (scrollLeft >= halfWidth - 50) {
          // Instant reset to the start for seamless continuity
          container.scrollTo({ left: 0, behavior: 'instant' as any });

          // Trigger the next move shortly after the reset
          setTimeout(() => {
            container.scrollBy({ left: scrollAmount, behavior: 'smooth' });
          }, 50);
        } else {
          // Standard move-pause step
          container.scrollBy({ left: scrollAmount, behavior: 'smooth' });
        }
      }, moveInterval);
    };

    startAutoScroll();

    return () => clearInterval(intervalId);
  }, [isInteracting, speed, moveInterval, scrollAmount]);

  const handleInteractionStart = () => {
    setIsInteracting(true);
    if (interactionTimerRef.current) clearTimeout(interactionTimerRef.current);
  };

  const handleInteractionEnd = () => {
    // Resume auto-scroll after 3 seconds of silence
    interactionTimerRef.current = window.setTimeout(() => {
      setIsInteracting(false);
    }, 3000);
  };

  return (
    <div className="relative group py-10">
      {/* Edge Fades for visual depth */}
      <div className="absolute inset-y-0 left-0 w-32 bg-gradient-to-r from-[#050a1b] to-transparent z-10 pointer-events-none"></div>
      <div className="absolute inset-y-0 right-0 w-32 bg-gradient-to-l from-[#050a1b] to-transparent z-10 pointer-events-none"></div>

      {/* Scrollable Container with Snap Points */}
      <div 
        ref={containerRef}
        className="flex items-center gap-12 overflow-x-auto no-scrollbar cursor-grab active:cursor-grabbing px-12"
        style={{ scrollSnapType: 'x proximity' }}
        onMouseDown={handleInteractionStart}
        onMouseUp={handleInteractionEnd}
        onMouseLeave={handleInteractionEnd}
        onTouchStart={handleInteractionStart}
        onTouchEnd={handleInteractionEnd}
      >
        {/* Double items for infinite illusion */}
        {[...items, ...items].map((item, idx) => (
          <div key={idx} className="flex-shrink-0" style={{ scrollSnapAlign: 'start' }}>
            {item}
          </div>
        ))}
      </div>

      {/* UI Hint: Informs users they can interact manually */}
      <div className="absolute bottom-2 left-1/2 -translate-x-1/2 opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none">
        <span className="text-[10px] text-gray-500 font-bold tracking-widest uppercase bg-black/60 px-4 py-1.5 rounded-full border border-white/10 backdrop-blur-sm">
          Swipe or Drag to Explore
        </span>
      </div>
    </div>
  );
};

export default AutoSlider;

import React, { useRef, useEffect, useState } from 'react';

interface AutoSliderProps {
  items: React.ReactNode[];
  speed?: 'slow' | 'normal' | 'fast';
  reverse?: boolean;
  delay?: number;
}

const AutoSlider: React.FC<AutoSliderProps> = ({ items, speed = 'normal', reverse = false, delay = 0 }) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const [isInteracting, setIsInteracting] = useState(false);
  const interactionTimerRef = useRef<number | null>(null);

  // Dynamic cycle timings (ms) and scroll distance
  const timings = {
    slow: { moveInterval: 4000, scrollAmount: 400 },
    normal: { moveInterval: 2500, scrollAmount: 450 },
    fast: { moveInterval: 1800, scrollAmount: 500 }
  };

  const { moveInterval, scrollAmount } = timings[speed];
  const directionMultiplier = reverse ? -1 : 1;

  useEffect(() => {
    const container = containerRef.current;
    if (!container) return;

    // If reverse, start at the halfway point to allow leftward scrolling
    if (reverse) {
      const halfWidth = container.scrollWidth / 2;
      container.scrollLeft = halfWidth;
    }

    let intervalId: number;
    let initialDelayTimeout: number;

    const startAutoScroll = () => {
      intervalId = window.setInterval(() => {
        if (!container || isInteracting) return;

        const { scrollLeft, scrollWidth, clientWidth } = container;
        const halfWidth = scrollWidth / 2;

        if (!reverse) {
          // Forward logic
          if (scrollLeft >= halfWidth - 50) {
            container.scrollTo({ left: 0, behavior: 'instant' as any });
            setTimeout(() => {
              container.scrollBy({ left: scrollAmount * directionMultiplier, behavior: 'smooth' });
            }, 50);
          } else {
            container.scrollBy({ left: scrollAmount * directionMultiplier, behavior: 'smooth' });
          }
        } else {
          // Reverse logic
          if (scrollLeft <= 50) {
            container.scrollTo({ left: halfWidth, behavior: 'instant' as any });
            setTimeout(() => {
              container.scrollBy({ left: scrollAmount * directionMultiplier, behavior: 'smooth' });
            }, 50);
          } else {
            container.scrollBy({ left: scrollAmount * directionMultiplier, behavior: 'smooth' });
          }
        }
      }, moveInterval);
    };

    // Apply the initial stagger delay
    initialDelayTimeout = window.setTimeout(() => {
      startAutoScroll();
    }, delay);

    return () => {
      clearInterval(intervalId);
      clearTimeout(initialDelayTimeout);
    };
  }, [isInteracting, speed, moveInterval, scrollAmount, reverse, delay, directionMultiplier]);

  const handleInteractionStart = () => {
    setIsInteracting(true);
    if (interactionTimerRef.current) clearTimeout(interactionTimerRef.current);
  };

  const handleInteractionEnd = () => {
    interactionTimerRef.current = window.setTimeout(() => {
      setIsInteracting(false);
    }, 3000);
  };

  return (
    <div className="relative group py-6">
      {/* Edge Fades */}
      <div className="absolute inset-y-0 left-0 w-32 bg-gradient-to-r from-[#050a1b] to-transparent z-10 pointer-events-none"></div>
      <div className="absolute inset-y-0 right-0 w-32 bg-gradient-to-l from-[#050a1b] to-transparent z-10 pointer-events-none"></div>

      <div 
        ref={containerRef}
        className="flex items-center gap-12 overflow-x-auto no-scrollbar cursor-grab active:cursor-grabbing px-12"
        style={{ scrollSnapType: 'x proximity' }}
        onMouseDown={handleInteractionStart}
        onMouseUp={handleInteractionEnd}
        onMouseLeave={handleInteractionEnd}
        onTouchStart={handleInteractionStart}
        onTouchEnd={handleInteractionEnd}
      >
        {[...items, ...items].map((item, idx) => (
          <div key={idx} className="flex-shrink-0" style={{ scrollSnapAlign: 'start' }}>
            {item}
          </div>
        ))}
      </div>

      <div className="absolute bottom-0 left-1/2 -translate-x-1/2 opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none">
        <span className="text-[10px] text-gray-500 font-bold tracking-widest uppercase bg-black/60 px-4 py-1.5 rounded-full border border-white/10 backdrop-blur-sm">
          Swipe or Drag to Explore
        </span>
      </div>
    </div>
  );
};

export default AutoSlider;

import React, { useRef, useEffect, useState } from 'react';

interface AutoSliderProps {
  items: React.ReactNode[];
  speed?: 'slow' | 'normal' | 'fast';
  reverse?: boolean;
  delay?: number;
}

const AutoSlider: React.FC<AutoSliderProps> = ({ items, speed = 'normal', reverse = false, delay = 0 }) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const [isInteracting, setIsInteracting] = useState(false);
  const interactionTimerRef = useRef<number | null>(null);

  // Dynamic cycle timings (ms) and scroll distance
  const timings = {
    slow: { moveInterval: 4000, scrollAmount: 400 },
    normal: { moveInterval: 2500, scrollAmount: 450 },
    fast: { moveInterval: 1800, scrollAmount: 500 }
  };

  const { moveInterval, scrollAmount } = timings[speed];
  const directionMultiplier = reverse ? -1 : 1;

  // Seamless loop handler for both manual and auto scrolling
  const handleScroll = () => {
    const container = containerRef.current;
    if (!container) return;

    const { scrollLeft, scrollWidth } = container;
    const halfWidth = scrollWidth / 2;

    // If we scroll past the halfway point (end of the first set), jump back to start
    if (scrollLeft >= halfWidth) {
      container.scrollLeft = scrollLeft - halfWidth;
    } 
    // If we scroll before the start (start of the first set), jump to halfway
    else if (scrollLeft <= 0 && reverse) {
      container.scrollLeft = halfWidth;
    }
  };

  useEffect(() => {
    const container = containerRef.current;
    if (!container) return;

    // Initial position for reverse mode to allow immediate leftward scroll
    if (reverse) {
      container.scrollLeft = container.scrollWidth / 2;
    }

    let intervalId: number;
    let initialDelayTimeout: number;

    const startAutoScroll = () => {
      intervalId = window.setInterval(() => {
        if (!container || isInteracting) return;

        // Execute the "step" move
        container.scrollBy({ 
          left: scrollAmount * directionMultiplier, 
          behavior: 'smooth' 
        });
      }, moveInterval);
    };

    initialDelayTimeout = window.setTimeout(() => {
      startAutoScroll();
    }, delay);

    return () => {
      clearInterval(intervalId);
      clearTimeout(initialDelayTimeout);
    };
  }, [isInteracting, speed, moveInterval, scrollAmount, reverse, delay, directionMultiplier]);

  const handleInteractionStart = () => {
    setIsInteracting(true);
    if (interactionTimerRef.current) clearTimeout(interactionTimerRef.current);
  };

  const handleInteractionEnd = () => {
    interactionTimerRef.current = window.setTimeout(() => {
      setIsInteracting(false);
    }, 3000);
  };

  return (
    <div className="relative group py-6">
      {/* Edge Fades */}
      <div className="absolute inset-y-0 left-0 w-32 bg-gradient-to-r from-[#050a1b] to-transparent z-10 pointer-events-none"></div>
      <div className="absolute inset-y-0 right-0 w-32 bg-gradient-to-l from-[#050a1b] to-transparent z-10 pointer-events-none"></div>

      <div 
        ref={containerRef}
        onScroll={handleScroll}
        className="flex items-center gap-12 overflow-x-auto no-scrollbar cursor-grab active:cursor-grabbing px-12"
        onMouseDown={handleInteractionStart}
        onMouseUp={handleInteractionEnd}
        onMouseLeave={handleInteractionEnd}
        onTouchStart={handleInteractionStart}
        onTouchEnd={handleInteractionEnd}
      >
        {/* Doubling items to ensure there is always content to scroll into */}
        {[...items, ...items].map((item, idx) => (
          <div key={idx} className="flex-shrink-0">
            {item}
          </div>
        ))}
      </div>

      <div className="absolute bottom-0 left-1/2 -translate-x-1/2 opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none">
        <span className="text-[10px] text-gray-500 font-bold tracking-widest uppercase bg-black/60 px-4 py-1.5 rounded-full border border-white/10 backdrop-blur-sm">
          Swipe or Drag to Explore
        </span>
      </div>
    </div>
  );
};

export default AutoSlider;

import React, { useRef, useEffect, useState } from 'react';

interface AutoSliderProps {
  items: React.ReactNode[];
  speed?: 'slow' | 'normal' | 'fast';
  reverse?: boolean;
  delay?: number;
  type?: 'stepped' | 'continuous';
}

const AutoSlider: React.FC<AutoSliderProps> = ({ 
