  speed = 'normal', 
  reverse = false, 
  delay = 0,
  type = 'stepped'
}) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const [isInteracting, setIsInteracting] = useState(false);
  const interactionTimerRef = useRef<number | null>(null);

  // Configuration for both modes
  const config = {
    stepped: {
      slow: { interval: 4000, amount: 400 },
      normal: { interval: 2200, amount: 450 },
      fast: { interval: 1500, amount: 500 }
    },
    continuous: {
      slow: 0.5,
      normal: 1,
      fast: 1.8 // Increased speed for "without stopping" feel
    }
  };

  const handleScrollReset = () => {
    const container = containerRef.current;
    if (!container) return;

    const { scrollLeft, scrollWidth } = container;
    const thirdWidth = scrollWidth / 3;

    // Reset logic for 3x cloning: Keep the user in the middle third
    if (scrollLeft >= thirdWidth * 2) {
      container.scrollLeft = scrollLeft - thirdWidth;
    } else if (scrollLeft <= 0) {
      container.scrollLeft = thirdWidth;
    }
  };

  useEffect(() => {
    const container = containerRef.current;
    if (!container) return;

    // Center the scroll to the middle third for the loop to work both ways
    container.scrollLeft = container.scrollWidth / 3;

    let timerId: number;
    let frameId: number;

    const startSteppedScroll = () => {
      const { interval, amount } = config.stepped[speed];
      timerId = window.setInterval(() => {
        if (isInteracting) return;
        container.scrollBy({ 
          left: amount * (reverse ? -1 : 1), 
          behavior: 'smooth' 
        });
      }, interval);
    };

    const startContinuousScroll = () => {
      const step = config.continuous[speed] * (reverse ? -1 : 1);
      const animate = () => {
        if (!isInteracting && container) {
          container.scrollLeft += step;
          handleScrollReset();
        }
        frameId = requestAnimationFrame(animate);
      };
      frameId = requestAnimationFrame(animate);
    };

    const timeoutId = window.setTimeout(() => {
      if (type === 'stepped') startSteppedScroll();
      else startContinuousScroll();
    }, delay);

    return () => {
      clearTimeout(timeoutId);
      if (timerId) clearInterval(timerId);
      if (frameId) cancelAnimationFrame(frameId);
    };
  }, [isInteracting, speed, reverse, delay, type]);

  const handleInteractionStart = () => {
    setIsInteracting(true);
    if (interactionTimerRef.current) clearTimeout(interactionTimerRef.current);
  };

  const handleInteractionEnd = () => {
    interactionTimerRef.current = window.setTimeout(() => {
      setIsInteracting(false);
    }, 2000);
  };

  return (
    <div className="relative group py-4">
      {/* Visual edge fades */}
      <div className="absolute inset-y-0 left-0 w-40 bg-gradient-to-r from-[#050a1b] to-transparent z-10 pointer-events-none"></div>
      <div className="absolute inset-y-0 right-0 w-40 bg-gradient-to-l from-[#050a1b] to-transparent z-10 pointer-events-none"></div>

      <div 
        ref={containerRef}
        onScroll={type === 'stepped' ? handleScrollReset : undefined}
        className="flex items-center gap-16 overflow-x-auto no-scrollbar cursor-grab active:cursor-grabbing px-10"
        onMouseDown={handleInteractionStart}
        onMouseUp={handleInteractionEnd}
        onMouseLeave={handleInteractionEnd}
        onTouchStart={handleInteractionStart}
        onTouchEnd={handleInteractionEnd}
      >
        {/* Triple clone ensures the loop is physically impossible to break regardless of screen size */}
        {[...items, ...items, ...items].map((item, idx) => (
          <div key={idx} className="flex-shrink-0">
            {item}
          </div>
        ))}
      </div>

      <div className="absolute bottom-[-10px] left-1/2 -translate-x-1/2 opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none">
        <span className="text-[9px] text-emerald-500/60 font-black tracking-[0.3em] uppercase bg-black/80 px-4 py-2 rounded-full border border-emerald-500/20 backdrop-blur-md">
          Manual Scroll Active
        </span>
      </div>
    </div>
  );
};

