import React, { useState, useEffect } from 'react';
import { Link, useLocation } from 'react-router-dom';

const Navbar: React.FC = () => {
  const [isScrolled, setIsScrolled] = useState(false);
  const location = useLocation();

  useEffect(() => {
    const handleScroll = () => {
      setIsScrolled(window.scrollY > 20);
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const isActive = (path: string) => location.pathname === path;

  return (
    <nav className={`fixed top-0 left-0 right-0 z-50 transition-all duration-300 ${isScrolled ? 'bg-[#050a1b]/80 backdrop-blur-lg border-b border-white/10 py-5' : 'bg-transparent py-10'}`}>
      <div className="container mx-auto px-10 flex justify-between items-center">
        <Link to="/" className="flex items-center gap-4 group">
          <div className="w-10 h-10 bg-gradient-to-tr from-[#00ff88] to-emerald-400 rounded-lg flex items-center justify-center neon-glow group-hover:scale-110 transition-transform">
            <span className="text-black font-extrabold text-xl italic">W</span>
          </div>
          <span className="text-2xl font-bold tracking-tighter chrome-text">WILD<span className="text-[#00ff88]">MARK</span></span>
        </Link>

        <div className="flex items-center gap-10 md:gap-14">
          <Link 
            to="/" 
            className={`text-[11px] md:text-sm font-bold tracking-[0.3em] transition-all duration-300 ${isActive('/') ? 'text-[#00ff88]' : 'hover:text-[#00ff88] text-white/60 hover:translate-y-[-1px]'}`}
          >
            HOME
          </Link>
          <Link 
            to="/about" 
            className={`text-[11px] md:text-sm font-bold tracking-[0.3em] transition-all duration-300 ${isActive('/about') ? 'text-[#00ff88]' : 'hover:text-[#00ff88] text-white/60 hover:translate-y-[-1px]'}`}
          >
            ABOUT
          </Link>
          <Link 
            to="/works" 
            className={`text-[11px] md:text-sm font-bold tracking-[0.3em] transition-all duration-300 ${isActive('/works') ? 'text-[#00ff88]' : 'hover:text-[#00ff88] text-white/60 hover:translate-y-[-1px]'}`}
          >
            WORKS
          </Link>
          <a 
            href="#contact" 
            className="text-[11px] md:text-sm font-bold tracking-[0.3em] hover:text-[#00ff88] text-white/60 transition-all duration-300 uppercase hover:translate-y-[-1px]"
          >
            CONTACT US
          </a>
        </div>
      </div>
    </nav>
  );
};

export default Navbar;

import React from 'react';
import { useParams, Link } from 'react-router-dom';
import { CLIENTS } from '../constants';

const ProjectDetail: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const client = CLIENTS.find(c => c.id === id);

  if (!client) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <div className="text-center">
          <h2 className="text-4xl font-bold mb-6">Project Not Found</h2>
          <Link to="/works" className="text-[#00ff88] font-bold underline text-sm tracking-widest uppercase">Go back to Works</Link>
        </div>
      </div>
    );
  }

  return (
    <div className="pt-48 pb-40">
      <div className="container mx-auto px-10">
        <Link to="/works" className="inline-flex items-center gap-4 text-gray-500 hover:text-[#00ff88] font-black text-xs uppercase tracking-[0.4em] mb-20 transition-all duration-300">
          <span className="text-lg">←</span> Back to Works
        </Link>

        <div className="grid lg:grid-cols-2 gap-32 items-center mb-64">
          <div className="reveal">
            <span className="text-[#00ff88] font-black text-xs tracking-[0.6em] uppercase mb-8 block">{client.industry}</span>
            <h1 className="text-7xl md:text-[8rem] font-black chrome-text uppercase mb-12 leading-[0.85] tracking-tighter">{client.name}</h1>
            <p className="text-2xl text-gray-400 leading-relaxed mb-16 font-light">
              {client.description}
            </p>
            <div className="flex flex-wrap gap-16">
              <div>
                <p className="text-gray-500 text-[10px] font-black uppercase tracking-[0.4em] mb-4">Campaign</p>
                <p className="text-2xl font-bold uppercase tracking-tight">{client.mainCampaign}</p>
              </div>
              <div>
                <p className="text-gray-500 text-[10px] font-black uppercase tracking-[0.4em] mb-4">Deliverable</p>
                <p className="text-2xl font-bold uppercase tracking-tight">Branding & Strategy</p>
              </div>
            </div>
          </div>
          <div className="glass-card rounded-[48px] p-20 aspect-square flex items-center justify-center relative overflow-hidden reveal" style={{ animationDelay: '200ms' }}>
            <div className="absolute inset-0 bg-[#00ff88]/5 animate-pulse"></div>
            <img src={client.logo} alt={client.name} className="w-80 h-80 object-contain relative z-10 drop-shadow-[0_25px_50px_rgba(0,0,0,0.5)]" />
          </div>
        </div>

        <div className="space-y-24">
          <div className="flex items-center justify-between border-b border-white/10 pb-8">
            <h2 className="text-4xl font-black uppercase tracking-tighter">Case Study</h2>
            <span className="text-[#00ff88] font-black text-xs tracking-[0.4em] uppercase">Visual Assets</span>
          </div>
          <div className="grid md:grid-cols-2 gap-16">
            {client.portfolioImages.map((img, idx) => (
              <div key={idx} className={`rounded-[48px] overflow-hidden glass-card ${idx === 0 && client.portfolioImages.length > 2 ? 'md:col-span-2 aspect-[21/9]' : 'aspect-square md:aspect-video'}`}>
                <img src={img} alt={`${client.name} work ${idx}`} className="w-full h-full object-cover hover:scale-105 transition-transform duration-1000" />
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
};

export default ProjectDetail;
